package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import java.sql.Timestamp;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.planning.schedule.v1.*;
/** Planning owns schedules, immutable revisions and their local transactional Outbox. */
final class ScheduleStore {
 record Input(String title,String description,String startsAt,String endsAt,String timeZone,UUID taskId){}
 record Schedule(UUID scheduleId,UUID spaceId,String visibility,String state,long version,String title,String description,String startsAt,String endsAt,String timeZone,String startsLocal,String endsLocal,String startsOffset,String endsOffset,UUID taskId,String createdAt,String updatedAt){}
 record Creation(Schedule schedule,boolean replay){}
 record Summary(UUID scheduleId,String title,String startsAt,String endsAt,String timeZone,String startsLocal,String endsLocal,String startsOffset,String endsOffset,UUID taskId,long version,String updatedAt,String state){}
 record Page(UUID spaceId,String state,String taskFilter,String from,String to,String timeZone,List<Summary> items,String nextAfter){}
 record Revision(UUID revisionId,UUID scheduleId,long version,UUID actorId,String occurredAt,Schedule snapshot){}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 ScheduleStore(DataSource source,Clock clock){jdbc=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);}
 static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Schedule unavailable");}
 private String hash(Input input){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(input)));}catch(Exception e){throw new IllegalStateException(e);}}
 private Schedule value(UUID id,UUID space,long version,String state,Input input,String createdAt,String updatedAt){var z=ScheduleRules.zone(input.timeZone());var a=ScheduleRules.instant(input.startsAt()).atZone(z);var b=ScheduleRules.instant(input.endsAt()).atZone(z);return new Schedule(id,space,"PRIVATE",state,version,input.title(),input.description(),input.startsAt(),input.endsAt(),input.timeZone(),ScheduleRules.LOCAL.format(a),ScheduleRules.LOCAL.format(b),a.getOffset().toString(),b.getOffset().toString(),input.taskId(),createdAt,updatedAt);}
 Creation create(UUID space,UUID actor,String key,Input input,String trace){ScheduleRules.id(space);ScheduleRules.id(actor);GoalRules.trace(trace);ScheduleRules.input(input);if(key==null||!key.matches("[0-9a-f]{32}"))throw ScheduleRules.bad();String hash=hash(input);return tx.execute(s->{var id=ids.next();var now=clock.instant();int inserted=jdbc.update("INSERT INTO schedule(schedule_id,space_id,visibility,state,version,title,description,starts_at,ends_at,time_zone,task_id,created_at,updated_at,request_key,request_hash) VALUES (?,?,'PRIVATE','ACTIVE',1,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(space_id,request_key) DO NOTHING",id,space,input.title(),input.description(),OffsetDateTime.ofInstant(ScheduleRules.instant(input.startsAt()),ZoneOffset.UTC),OffsetDateTime.ofInstant(ScheduleRules.instant(input.endsAt()),ZoneOffset.UTC),input.timeZone(),input.taskId(),Timestamp.from(now),Timestamp.from(now),key,hash);
 if(inserted==0){var rows=jdbc.query("SELECT s.request_hash,r.snapshot::text FROM schedule s JOIN schedule_revision r ON r.schedule_id=s.schedule_id AND r.version=1 WHERE s.space_id=? AND s.request_key=?",(rs,n)->Map.entry(rs.getString(1),rs.getString(2)),space,key);if(rows.size()!=1)throw new IllegalStateException("Original schedule creation missing");if(!MessageDigest.isEqual(hash.getBytes(StandardCharsets.US_ASCII),rows.getFirst().getKey().getBytes(StandardCharsets.US_ASCII)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Creation key already represents different schedule input");return new Creation(json.readValue(rows.getFirst().getValue(),Schedule.class),true);}
 checkTask(space,input.taskId());var value=value(id,space,1,"ACTIVE",input,now.toString(),now.toString());revision(value,actor,trace,"ScheduleCreated");return new Creation(value,false);});}
 private Schedule decode(String raw,UUID space,UUID id,long version,String state){if(raw==null)throw new IllegalStateException("Schedule revision missing");var value=json.readValue(raw,Schedule.class);if(!value.spaceId().equals(space)||!value.scheduleId().equals(id)||value.version()!=version||!value.state().equals(state)||!value.visibility().equals("PRIVATE"))throw new IllegalStateException("Schedule revision mismatch");return value;}
 private Schedule current(UUID space,UUID id,boolean lock,boolean active){ScheduleRules.id(space);ScheduleRules.id(id);if(lock){record Head(long version,String state){}var heads=jdbc.query("SELECT version,state FROM schedule WHERE space_id=? AND schedule_id=? FOR UPDATE",(rs,n)->new Head(rs.getLong(1),rs.getString(2)),space,id);if(heads.isEmpty()||active&&!heads.getFirst().state().equals("ACTIVE"))throw missing();var h=heads.getFirst();String raw=jdbc.queryForObject("SELECT snapshot::text FROM schedule_revision WHERE schedule_id=? AND version=?",String.class,id,h.version());return decode(raw,space,id,h.version(),h.state());}var rows=jdbc.query("SELECT g.version,g.state,r.snapshot::text FROM schedule g LEFT JOIN schedule_revision r ON r.schedule_id=g.schedule_id AND r.version=g.version WHERE g.space_id=? AND g.schedule_id=?",(rs,n)->decode(rs.getString(3),space,id,rs.getLong(1),rs.getString(2)),space,id);if(rows.isEmpty()||active&&!rows.getFirst().state().equals("ACTIVE"))throw missing();return rows.getFirst();}
 Schedule get(UUID space,UUID id){return current(space,id,false,true);}
 Schedule change(UUID space,UUID id,UUID actor,long expected,Input input,boolean retire,String trace){ScheduleRules.id(actor);GoalRules.trace(trace);if(expected<1)throw ScheduleRules.bad();if(!retire)ScheduleRules.input(input);return tx.execute(s->{var prior=current(space,id,true,true);if(prior.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Schedule changed; inspect latest before saving");if(!retire&&new Input(prior.title(),prior.description(),prior.startsAt(),prior.endsAt(),prior.timeZone(),prior.taskId()).equals(input))return prior;if(!retire&&!Objects.equals(prior.taskId(),input.taskId()))checkTask(space,input.taskId());var now=clock.instant().toString();var value=retire?new Schedule(id,space,"PRIVATE","RETIRED",Math.addExact(prior.version(),1),prior.title(),prior.description(),prior.startsAt(),prior.endsAt(),prior.timeZone(),prior.startsLocal(),prior.endsLocal(),prior.startsOffset(),prior.endsOffset(),prior.taskId(),prior.createdAt(),now):value(id,space,Math.addExact(prior.version(),1),"ACTIVE",input,prior.createdAt(),now);jdbc.update("UPDATE schedule SET title=?,description=?,starts_at=?,ends_at=?,time_zone=?,task_id=?,state=?,version=?,updated_at=? WHERE schedule_id=?",value.title(),value.description(),OffsetDateTime.ofInstant(ScheduleRules.instant(value.startsAt()),ZoneOffset.UTC),OffsetDateTime.ofInstant(ScheduleRules.instant(value.endsAt()),ZoneOffset.UTC),value.timeZone(),value.taskId(),value.state(),value.version(),Timestamp.from(Instant.parse(value.updatedAt())),id);revision(value,actor,trace,retire?"ScheduleRetired":"ScheduleUpdated");return value;});}
 private void checkTask(UUID space,UUID task){if(task==null)return;var rows=jdbc.query("SELECT state FROM task WHERE space_id=? AND task_id=? FOR UPDATE",(rs,n)->rs.getString(1),space,task);if(rows.isEmpty()||!rows.getFirst().equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Task unavailable for schedule link");}
 Page list(UUID space,String state,String taskFilter,ScheduleRules.Window w,String after,int limit){ScheduleRules.id(space);if(!Set.of("ACTIVE","RETIRED").contains(state)||taskFilter==null||limit<1||limit>100)throw ScheduleRules.bad();UUID task=null;if(!Set.of("ALL","NONE").contains(taskFilter))task=ScheduleRules.id(taskFilter);var cursor=ScheduleRules.cursor(after,space,state,taskFilter,w);var args=new ArrayList<Object>();args.add(space);args.add(state);args.add(OffsetDateTime.ofInstant(w.end(),ZoneOffset.UTC));args.add(OffsetDateTime.ofInstant(w.start(),ZoneOffset.UTC));String sql="SELECT r.snapshot::text FROM schedule s JOIN schedule_revision r ON r.schedule_id=s.schedule_id AND r.version=s.version WHERE s.space_id=? AND s.state=? AND s.starts_at<? AND s.ends_at>?";if(taskFilter.equals("NONE"))sql+=" AND s.task_id IS NULL";else if(task!=null){sql+=" AND s.task_id=?";args.add(task);}if(cursor!=null){sql+=" AND (s.starts_at,s.schedule_id)>(?,?)";args.add(OffsetDateTime.ofInstant(cursor.start(),ZoneOffset.UTC));args.add(cursor.id());}sql+=" ORDER BY s.starts_at,s.schedule_id LIMIT ?";args.add(limit+1);var rows=jdbc.query(sql,(rs,n)->{var v=json.readValue(rs.getString(1),Schedule.class);if(!v.spaceId().equals(space)||!v.state().equals(state)||!v.visibility().equals("PRIVATE"))throw new IllegalStateException("Schedule revision mismatch");return new Summary(v.scheduleId(),v.title(),v.startsAt(),v.endsAt(),v.timeZone(),v.startsLocal(),v.endsLocal(),v.startsOffset(),v.endsOffset(),v.taskId(),v.version(),v.updatedAt(),v.state());},args.toArray());var page=List.copyOf(rows.subList(0,Math.min(rows.size(),limit)));var last=page.isEmpty()?null:page.getLast();return new Page(space,state,taskFilter,w.from(),w.to(),w.timeZone(),page,rows.size()>limit?ScheduleRules.cursor(space,state,taskFilter,w,last.startsAt(),last.scheduleId()):null);}
 List<Revision> history(UUID space,UUID id,long before,int limit){current(space,id,false,false);if(before<1||limit<1||limit>10)throw ScheduleRules.bad();return jdbc.query("SELECT revision_id,schedule_id,version,actor_id,occurred_at,snapshot::text FROM schedule_revision WHERE schedule_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getLong(3),rs.getObject(4,UUID.class),rs.getTimestamp(5).toInstant().toString(),json.readValue(rs.getString(6),Schedule.class)),id,before,limit);}
 private void revision(Schedule value,UUID actor,String trace,String type){UUID revision=ids.next(),event=ids.next();var now=Instant.parse(value.updatedAt());jdbc.update("INSERT INTO schedule_revision VALUES (?,?,?,?,?,?::jsonb)",revision,value.scheduleId(),value.version(),actor,Timestamp.from(now),json.writeValueAsString(value));var payload=ScheduleChangedPayloadV1.newBuilder().setScheduleId(value.scheduleId().toString()).setRevisionId(revision.toString()).setVersion(value.version()).setVisibility("PRIVATE").setState(value.state()).setTitle(value.title()).setDescription(value.description()).setStartsAt(value.startsAt()).setEndsAt(value.endsAt()).setTimeZone(value.timeZone()).setTaskId(value.taskId()==null?"":value.taskId().toString()).setStartsLocal(value.startsLocal()).setEndsLocal(value.endsLocal()).setStartsOffset(value.startsOffset()).setEndsOffset(value.endsOffset()).setCreatedAt(value.createdAt()).setUpdatedAt(value.updatedAt()).build();var envelope=ScheduleEventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("planning-service").setAggregateType("Schedule").setAggregateId(value.scheduleId().toString()).setSpaceId(value.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(payload.toByteString()).build();jdbc.update("INSERT INTO outbox_event VALUES (?,'schedule',?,?,?,?, 'planning','schedule-events','1',?)",event,value.scheduleId(),type,Timestamp.from(now),trace,envelope.toByteArray());}
}
